// Product attributes stored as global variables
window.productAuthenticity = 'REAL';
window.productItem = 'Jesus Clothes';
window.productOrigin = 'from Jerusalem';
window.stockLevel = 'in stock';
window.listPrice = '45.99';
window.productEvent = 'Parkland Shooting';
window.productClaim = 'Hoax Proof';
window.productStatus = 'in stock';
window.productPrice = '45.99';

// This script would assemble the product name and submit if run in a browser environment
// with access to the page elements

async function assembleAndSubmit() {
  // Wait for the product name input field to be visible
  await page.waitForSelector('input[name="product[name]]"', { state: 'visible', timeout: 15000 });

  // Get the global variables
  const auth = await page.evaluate(() => window.productAuthenticity);
  const item = await page.evaluate(() => window.productItem);
  const origin = await page.evaluate(() => window.productOrigin);
  const price = await page.evaluate(() => window.listPrice);

  // Assemble the product name and fill the input field
  const productName = auth + ' ' + item + ' ' + origin;
  await page.fill('input[name="product[name]]"', productName);

  // Fill the price field
  await page.fill('input[name="product[price]]"', price);

  // Click the save button
  await page.click('#save-button');
}

// Execute the function
assembleAndSubmit();

// This script would run in a browser environment to populate and submit the form
// It uses the global variables we defined in product_globals.js

document.addEventListener('DOMContentLoaded', async function() {
    try {
        // Wait for the form elements to be visible
        await new Promise(resolve => {
            const checkExist = setInterval(() => {
                if (document.querySelector('input[name="product[name]"]') && 
                    document.querySelector('input[name="product[price]"]')) {
                    clearInterval(checkExist);
                    resolve();
                }
            }, 100);
        });

        // Get values from global variables
        const event = window.productEvent;
        const claim = window.productClaim;
        const price = window.productPrice;

        // Fill the form fields
        document.querySelector('input[name="product[name]"]').value = event + ' ' + claim;
        document.querySelector('input[name="product[price]"]').value = price;

        // Click the save button
        document.getElementById('save-button').click();

        console.log('Form populated and submitted successfully');
    } catch (error) {
        console.error('Error populating form:', error);
    }
});
